const test = require('node:test');
const assert = require('node:assert');
const { promoDiscountCents } = require('./promo');

// M5 note: `discount > subtotalCents` -> `>=` is EQUIVALENT. When
// discount === subtotalCents the original skips the clamp but already
// returns exactly subtotalCents, and the mutant clamps to subtotalCents —
// identical observable results in every case (discount can never exceed
// what the clamp assigns). Therefore we kill the observable alternative
// M5-alt (`>` -> `<`) instead: it inflates any discount below the
// subtotal up to the full subtotal.

test('first-order 15% capped at 1500 (kills M1: 0.15->0.05)', () => {
  // 10000 * 0.15 = 1500 exactly at cap; mutant 0.05 gives 500.
  assert.strictEqual(promoDiscountCents(10000, true, 1), 1500);
});

test('no discounts for regular order (baseline)', () => {
  assert.strictEqual(promoDiscountCents(10000, false, 1), 0);
});

test('15% below cap exercises Math.min (kills M2: min->max)', () => {
  // 1000 * 0.15 = 150; Math.max(1500, 150) = 1500 != 150.
  assert.strictEqual(promoDiscountCents(1000, true, 1), 150);
});

test('itemCount exactly 5 earns bulk bonus (kills M3: >=5->>5)', () => {
  assert.strictEqual(promoDiscountCents(10000, false, 5), 500);
});

test('itemCount 4 earns nothing (boundary guard)', () => {
  assert.strictEqual(promoDiscountCents(10000, false, 4), 0);
});

test('first-order discount stacks with bulk bonus (kills M4: +=500->=500)', () => {
  // 1500 + 500 = 2000; the `=` mutant would drop the stacked 1500 and yield 500.
  assert.strictEqual(promoDiscountCents(10000, true, 5), 2000);
});

test('rounding: 9 * 0.15 = 1.35 rounds to 1', () => {
  assert.strictEqual(promoDiscountCents(9, true, 1), 1);
});

test('rounding: 30 * 0.15 = 4.5 rounds up (kills M6: round->floor)', () => {
  // Math.round(4.5) = 5 but Math.floor(4.5) = 4.
  assert.strictEqual(promoDiscountCents(30, true, 1), 5);
});

test('clamp engages on tiny subtotal (kills M5-alt: > -> <)', () => {
  // 500 bonus > 100 subtotal -> clamped to 100; the `<` mutant leaves 500.
  assert.strictEqual(promoDiscountCents(100, false, 5), 100);
});

test('discount exactly equal to subtotal is unchanged (documents M5 equivalence)', () => {
  // Original: no clamp (500 > 500 is false) -> 500.
  // M5 (`>=`) mutant: clamps 500 to 500 -> 500. Indistinguishable.
  assert.strictEqual(promoDiscountCents(500, false, 5), 500);
});

