#!/usr/bin/env node
// Mutation harness: injects each mutant into a temp copy of promo.js,
// runs promo.test.js against it, and reports KILLED/SURVIVED.
'use strict';
const fs = require('fs');
const path = require('path');
const { execFileSync } = require('child_process');

const WORK = __dirname;
const SRC = path.join(WORK, 'promo.js');
const TMP = path.join(WORK, 'promo.mutant.tmp.js');

const original = fs.readFileSync(SRC, 'utf8');

const MUTANTS = [
  ['M1', '* 0.15', '* 0.05'],
  ['M2', 'Math.min(1500', 'Math.max(1500'],
  ['M3', 'itemCount >= 5', 'itemCount > 5'],
  ['M4', 'discount += 500', 'discount = 500'],
  // M5 (>=) is provably equivalent; we target the observable M5-alt instead.
  ['M5-alt', 'if (discount > subtotalCents)', 'if (discount < subtotalCents)'],
  ['M6', 'Math.round(', 'Math.floor('],
];

let allKilled = true;
const rows = [];

for (const [id, from, to] of MUTANTS) {
  const count = original.split(from).length - 1;
  if (count !== 1) {
    throw new Error(`Mutant ${id}: pattern ${JSON.stringify(from)} found ${count} times (expected exactly 1)`);
  }
  fs.writeFileSync(TMP, original.replace(from, to));
  let killed;
  try {
    execFileSync(process.execPath, ['--test', path.join(WORK, 'promo.test.js')], {
      cwd: WORK,
      stdio: ['ignore', 'ignore', 'ignore'],
      env: { ...process.env },
    });
    killed = false; // suite green on a mutant => mutant survived
  } catch {
    killed = true; // at least one test failed => mutant killed
  }
  if (!killed) allKilled = false;
  rows.push([id, killed]);
}

try { fs.unlinkSync(TMP); } catch {}

console.log('MUTANT   RESULT');
for (const [id, killed] of rows) {
  console.log(`${id.padEnd(9)}${killed ? 'KILLED' : 'SURVIVED'}`);
}
console.log(`\n${rows.filter(r => r[1]).length}/${rows.length} mutants killed`);
if (!allKilled) process.exit(1);

